window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-20091\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰήσομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 219 na letra ι · nº geral 20091</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. jôn. de ἰάομαι.</p></section></article>\n<article id=\"entry-dgp-20092\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰησοῦς,</h1><div class=\"entry-meta\"><span>DGP · ordem 220 na letra ι · nº geral 20092</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">voc. e gen. οῦ, dat. -οῖ, ac. -οῦν (ὁ) 1 Josué 2 Jesus. [hebr.]</p></section></article>\n<article id=\"entry-dgp-20093\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰήσων</h1><div class=\"entry-meta\"><span>DGP · ordem 221 na letra ι · nº geral 20093</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = Ἰάσων.</p></section></article>\n<article id=\"entry-dgp-20094\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἴητε</h1><div class=\"entry-meta\"><span>DGP · ordem 222 na letra ι · nº geral 20094</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2a pl. pres. subj. de εἶμι.</p></section></article>\n<article id=\"entry-dgp-20095\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰητήρ, ἰητρός</h1><div class=\"entry-meta\"><span>DGP · ordem 223 na letra ι · nº geral 20095</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ἰατήρ, ἰατρός.</p></section></article>\n<article id=\"entry-dgp-20096\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰῆτο</h1><div class=\"entry-meta\"><span>DGP · ordem 224 na letra ι · nº geral 20096</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3a sing. impf. jôn. de ἰάομαι.</p></section></article>\n<article id=\"entry-dgp-20097\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰθαγενής,</h1><div class=\"entry-meta\"><span>DGP · ordem 225 na letra ι · nº geral 20097</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. ἰθαιγενής, ής, ές 1 de nascimento legítimo 2 de origem nobre; natural; originário 3 indígena; nativo 4 que sopra diretamente (vento); genuíno 5 normal; regular. 〈ἰθύς1, γένος〉</p></section></article>\n<article id=\"entry-dgp-20098\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰθάκη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 226 na letra ι · nº geral 20098</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Ítaca, uma das ilhas jônicas.</p></section></article>\n<article id=\"entry-dgp-20099\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰθάκηνδε</h1><div class=\"entry-meta\"><span>DGP · ordem 227 na letra ι · nº geral 20099</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e Ἰθάκην δε, adv. para Ítaca, em direção a Ítaca.</p></section></article>\n<article id=\"entry-dgp-20100\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰθακήσιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 228 na letra ι · nº geral 20100</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Ítaca. 〈 Ἰθάκη〉</p></section></article>\n<article id=\"entry-dgp-20101\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἴθακος, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 229 na letra ι · nº geral 20101</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 de Ítaca ♦ ὁ Ἴθακος 2 o itacense (Ulisses). 〈 Ἰθάκη〉</p></section></article>\n<article id=\"entry-dgp-20102\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰθεῖα</h1><div class=\"entry-meta\"><span>DGP · ordem 230 na letra ι · nº geral 20102</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fem. de ἰθύς1.</p></section></article>\n<article id=\"entry-dgp-20103\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰθέως</h1><div class=\"entry-meta\"><span>DGP · ordem 231 na letra ι · nº geral 20103</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 diretamente 2 logo em seguida; imediatamente. 〈ἰθύς1〉</p></section></article>\n<article id=\"entry-dgp-20104\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἴθι</h1><div class=\"entry-meta\"><span>DGP · ordem 232 na letra ι · nº geral 20104</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2a sing. imper. pres. de εἶμι.</p></section></article>\n<article id=\"entry-dgp-20105\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἴθμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 233 na letra ι · nº geral 20105</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 marcha 2 movimento 3 passo; andamento 4 pés. 〈εἶμι〉</p></section></article>\n<article id=\"entry-dgp-20106\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰθύ</h1><div class=\"entry-meta\"><span>DGP · ordem 234 na letra ι · nº geral 20106</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">n. de ἰθύς1.</p></section></article>\n<article id=\"entry-dgp-20107\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰθύθριξ, ἰθύτριχος</h1><div class=\"entry-meta\"><span>DGP · ordem 235 na letra ι · nº geral 20107</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) de cabelos lisos. 〈ἰθύς1, θρίξ〉</p></section></article>\n<article id=\"entry-dgp-20108\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰθυμαχίη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 236 na letra ι · nº geral 20108</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. batalha campal; combate regular. 〈ἰθύς1, μάχη〉</p></section></article>\n<article id=\"entry-dgp-20109\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰθύντατα</h1><div class=\"entry-meta\"><span>DGP · ordem 237 na letra ι · nº geral 20109</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. superl. de ἰθύς2.</p></section></article>\n<article id=\"entry-dgp-20110\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰθύνετε</h1><div class=\"entry-meta\"><span>DGP · ordem 238 na letra ι · nº geral 20110</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2a pl., ἰθύνομεν 1a pl. pres. ind. ou pres. subj. ép. de ἰθύνω.</p></section></article>\n<article id=\"entry-dgp-20111\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰθύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 239 na letra ι · nº geral 20111</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἰθυνῶ, aor. ἴθυνα, perf. desus.; pas. aor. ἰθύνθην, perf. ἴθυμμαι) 1 alinhar; traçar em linha reta: ἐπὶ στάθμην ἴθυνε hom. alinhou [a madeira] com o prumo 2 dirigir ou guiar em linha reta, diretamente: βέλος δ᾽ ἴθυνεν Ἀθήνη ῥῖνα παρ᾽ ὀφθαλμόν hom. Atena dirigiu o dardo direto ao nariz, junto ao olho 3 dirigir; governar: Ζεὺς δ᾽ ἔμπης παντ᾽ ἰθύνει hom. Zeus, de todos os modos, governa tudo 4 corrigir: ἰθ. θανάτῳ her. fazer expiar com a morte, punir de morte ♦ méd. 5 conduzir; dirigir para si em linha reta: ἀλλήλων ἰθυνομένων δοῦρα hom. dirigindo suas lanças direto uns contra os outros ♦ pas. 6 (cavalo) ir reto; ir em linha reta: τὼ δ᾽ [ἵππω] ἰθυνθήτην hom. ambos os cavalos correram em linha reta. 〈ἰθύς1〉</p></section></article>\n<article id=\"entry-dgp-20112\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰθυπτίων, ωνος</h1><div class=\"entry-meta\"><span>DGP · ordem 240 na letra ι · nº geral 20112</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) que voa em linha reta, epít. de lança. 〈ἰθύς1, πέτομαι〉</p></section></article>\n<article id=\"entry-dgp-20113\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰθύς1, εῖα, ύ</h1><div class=\"entry-meta\"><span>DGP · ordem 241 na letra ι · nº geral 20113</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(comp. ἰθύτερος e ἰθύντερος, superl. ἰθύτατος e ἰθύντατος) 1 que vai em linha reta; reto; direto: ἰθεῖα ἀτραπός nic. rota em linha reta, ἰθεῖαν [ὁδον] her. em linha reta, ἐκ τῆς ἰθέης (jôn.) her. abertamente; declaradamente, πρὸς ἰθύ hom. frente a, κατ᾽ ἰθύ her. de frente 2 ereto: ἰθεῖα κεφαλή teóg. cabeça ereta, ὄρος ἰθύ ap. montanha a pique, íngreme 3 reto; sem desvios; equitativo; justo: ἰθεῖαι δίκαι hes. julgamentos retos, justos, ἰθὺς καὶ δίκαιος her. [homem] correto e justo ♦ ἰθύ adv. 4 = ἰθύς2 ♦ ἡ ἰθεῖα 5 [δίκη] julgamento reto, justo 6 justiça eqüitativa</p></section></article>\n<article id=\"entry-dgp-20114\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">: ἰθείῃ Διός</h1><div class=\"entry-meta\"><span>DGP · ordem 242 na letra ι · nº geral 20114</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ésql. pela justiça de Zeus.</p></section></article>\n<article id=\"entry-dgp-20115\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰθύς2</h1><div class=\"entry-meta\"><span>DGP · ordem 243 na letra ι · nº geral 20115</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(superl. ἰθύντατα) adv. 1 em linha reta; diretamente; face a face: ἰθὺς μαχέσασθαι hom. combater face a face 2 direto em direção a, gen., ἐπί ou πρός e ac.: ὁ ναυτικὸς στρατὸς ἔπλεε ἰθὺ τοῦ Ἴστρου her. a frota navegava reto para o Istro, ἰθὺς πρὸς τεῖχος ἐύδμητον hom. direto rumo à muralha bem construída 3 (tempo) logo; imediatamente: ὡς ἐσήιε ἐς τὸ μέγαρον ἰθὺς ἡ Πυθίη λέγει τάδε her. quando ele entrou no templo, imediatamente a Pítia disse isso 4 com equidade; com retidão; com justiça: δίκην ἰθύντατα εἰπεῖν hom. proferir o julgamento com suprema retidão.</p></section></article>\n<article id=\"entry-dgp-20116\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰθύς3</h1><div class=\"entry-meta\"><span>DGP · ordem 244 na letra ι · nº geral 20116</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só ac. sing. ἰθύν) (ἡ) 1 curso em linha reta: ἀν᾽ ἰθύν hom. em direção contrária; contra a correnteza 2 empreendimento; iniciativa</p></section></article>\n<article id=\"entry-dgp-20117\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">: ἄριστοι πᾶσαν ἐπ᾽ ἰθύν ἐστε</h1><div class=\"entry-meta\"><span>DGP · ordem 245 na letra ι · nº geral 20117</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">hom. em qualquer empreendimento vós sois os melhores 3 disposições; sentimentos; intenção: γυναικῶν γνώομεν ἰθύν hom. conheçamos a intenção das (nossas) mulheres.</p></section></article>\n<article id=\"entry-dgp-20118\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰθύτριχες, ἰθύτριχος</h1><div class=\"entry-meta\"><span>DGP · ordem 246 na letra ι · nº geral 20118</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">nom. pl. e gen. sing. de ἰθύθριξ.</p></section></article>\n<article id=\"entry-dgp-20119\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰθύω</h1><div class=\"entry-meta\"><span>DGP · ordem 247 na letra ι · nº geral 20119</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e aor. ἴθυσα) 1 ir para frente em linha reta; ir direto a; avançar, gen. ou ἐπί ou πρός e ac.: πάντες ἄκουον, ἴθυσαν δ᾽ ἐπὶ τεῖχος hom. todos (o) ouviam e foram direto ao alto do muro, ἔνθα καὶ ἔνθα ἴθυσε μάχη πεδίοιο hom. aqui e ali a batalha foi avançando na planíce 2 tender a; desejar intensamente, ac. ou inf. 〈ἰθύς1〉</p></section></article>\n<article id=\"entry-dgp-20120\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰθώμη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 248 na letra ι · nº geral 20120</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Itome, n. de um local da Tessália, e de um monte e fortaleza da Messênia.</p></section></article>\n<article id=\"entry-dgp-20121\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰθωμήτας</h1><div class=\"entry-meta\"><span>DGP · ordem 249 na letra ι · nº geral 20121</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e Ἰθωμάτας, α (masc.) dór. do monte Itome. 〈 Ἰθώμη〉</p></section></article>\n<article id=\"entry-dgp-20122\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκανός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 250 na letra ι · nº geral 20122</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 suficiente; bastante para algo, εἰς, πρός, ἐπί e ac., ὑπέρ e gen., ou inf.: ὑμῶν τοῦτο ἐνίοις ἱκανὸν ἔσται lís. para alguns de vós isto será suficiente, ἡ δημιουργικὴ τέχνη αὐτοῖς πρὸς τροφὴν ἱκανὴ βοηθὸς ἦν plat. a arte dos artesãos lhes era suficiente para a subsistência, ἱκανὴν μαρτυρίαν παρέχεται ὑπὲρ τοῦδε τοῦ λόγου plat. fornece uma prova suficiente para esta afirmação 2 assaz forte; assaz grande; assaz numeroso para algo, εἰς, πρός, ἐπί e ac., ὑπέρ e gen.: τοῦ σώματος ἰσχὺν ἱκανὴν ἐπὶ τοὺς πόνους ἔχειν plat. ter um vigor de corpo assaz forte para trabalhos pesados, ἱκανοῦ τινος ἀπολελυκότες φόβου τοὺς Ἕλληνας pol. tendo libertado os gregos de um grande medo, πλῆθος ἱκανὸν πλοίων pol. quantidade considerável de navios 3 capaz de, inf. ou ὥστε e inf.: ἔφοροι ἱκανοί εἰσι ζημιοῦν ὃν ἂν βούλωνται xen. os éforos são capazes (têm o poder) de punir quem eles desejem, φύσις ἀνθρώπων οὐδενὸς ἱκανὴ φύεται ὥστε γνῶναί τε τὰ συμφέροντα ἀνθρώποις εἰς πολιτείαν plat. a natureza de nenhum dentre os homens é capaz de saber o que para eles é mais proveitoso em relação à constituição da cidade 4 capaz; competente em, ac.: ἀνὴρ γνώμην ἱκανός her. homem capaz quanto ao julgamento, i. e., de bom julgamento, οἶμαι, ὦ πάτερ, πάνυ ἱκανοὺς τὴν ἰατρικὴν τέχνην ἕξειν μετ᾽ ἐμαυτοῦ ἄνδρας xen. creio, pai, que terei comigo homens competentes na medicina 5 bastante; longo (tempo): καὶ γὰρ ἱκανὸν χρόνον ἀπολλύμεθα καὶ κατατετρίμμεθα πλανώμενοι εἰς Λύκειον κἀκ Λικείων ar. de fato durante bastante tempo nós nos matamos e nos extenuamos indo para o Liceu e de lá saindo, ἐφ᾽ ἱκανόν, ἀφ᾽ ἱκανοῦ por um longo tempo, em grau suficiente ♦ ἱκανόν adv. 6 em abundância ♦ τὸ ἱκανόν 7 bíbl. fiança; caução; garantia: λαβεῖν τὸ ἱκανὸν παρά τινος n.t. receber de alguém uma fiança ♦ τὰ ἱκανά 8 quantia suficiente. 〈ἱκνέομαι〉</p></section></article>\n<article id=\"entry-dgp-20123\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκανέμεν</h1><div class=\"entry-meta\"><span>DGP · ordem 251 na letra ι · nº geral 20123</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. pres. ép. de ἱκάνω.</p></section></article>\n<article id=\"entry-dgp-20124\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκανότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 252 na letra ι · nº geral 20124</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 suficiência em quantidade ou extensão 2 aptidão; capacidade. 〈ἱκανός〉</p></section></article>\n<article id=\"entry-dgp-20125\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκανόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 253 na letra ι · nº geral 20125</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. 1 tornar suficiente, apropriado 2 impes. ἱκανοῦται basta; é suficiente a alguém, dat., algo, inf. ♦ pas. 3 contentar-se com, dat. 〈ἱκανός〉</p></section></article>\n<article id=\"entry-dgp-20126\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκάνω</h1><div class=\"entry-meta\"><span>DGP · ordem 254 na letra ι · nº geral 20126</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf. ἵκανον) 1 (pessoa) vir; ir a, ac., ἐς, ἐπί ou πρός e ac.: ἱκάνω νῆας Ἀχαιῶν hom. venho às naus dos aqueus, [ὄνειρος] καρπαλίμως δ᾽ ἵκανε θοὰς ἐπὶ νῆας Ἀχαιῶν hom. prontamente o sonho vinha até as rápidas naus dos acaios 2 (coisa) atingir; alcançar: φωνὴ δὲ οἱ αἰθερ᾽ ἵκανεν hom. a voz atingia o céu, δι᾽ ἠέρος αἰθέρ᾽ ἵκανεν hom. [o pinheiro] através do ar alcançava o éter 3 (sentimento, sensação) vir; atingir; invadir: μιν γλυκὺς ὕπνος ἱκάνει hom. o doce sono o invade, μιν ἄχος κραδίην καὶ θυμὸν ἵκανεν hom. a dor invade-lhe a alma e a coragem ♦ méd. 4 vir; atingir; chegar: νῦν τὰ σὰ γούναθ᾽ ἱκάνομαι hom. agora venho aos teus joelhos 5 sobrevir: χρειὼ γὰρ ἱκάνεται hom. a necessidade sobrevém.</p></section></article>\n<article id=\"entry-dgp-20127\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκανῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 255 na letra ι · nº geral 20127</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 de maneira suficiente; em quantidade ou qualidade suficiente; muito ♦ ἔχειν ἱκανῶς 2 ser suficiente para algo, πρός ou περί e ac. 3 (coisa) ser possível: ἐξαναχωρέειν οὐδετέροισι ἱκανῶς ἔχει her. a nenhum dos dois é possível recuar 4 ser ou ter suficientemente; grandemente; fortemente em algo, gen.: ἱκ. ἔχειν τοῦ βάθους plat. ter profundidade suficiente, i.e., ser muito profundo, ἱκ. ἔχειν ἐπιστήμης plat. ter uma ciência suficiente, i.e., grande.</p></section></article>\n<article id=\"entry-dgp-20128\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰκάριος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 256 na letra ι · nº geral 20128</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de Ícaro: πόντος Ἰκ. hom. mar de Ícaro, parte do mar Egeu entre as Cíclades e a Cária ♦ τὸ Ἰκάριον 2 mar de Ícaro. 〈 Ἴκαρος〉</p></section></article>\n<article id=\"entry-dgp-20129\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἴκαρος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 257 na letra ι · nº geral 20129</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Ícaro, filho de Dédalo.</p></section></article>\n<article id=\"entry-dgp-20130\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἴκελος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 258 na letra ι · nº geral 20130</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">semelhante a, dat.</p></section></article>\n<article id=\"entry-dgp-20131\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἵκεο</h1><div class=\"entry-meta\"><span>DGP · ordem 259 na letra ι · nº geral 20131</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2a sing. aor.2 ép. de ἱκνέομαι.</p></section></article>\n<article id=\"entry-dgp-20132\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκέσθαι</h1><div class=\"entry-meta\"><span>DGP · ordem 260 na letra ι · nº geral 20132</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 de ἱκνέομαι.</p></section></article>\n<article id=\"entry-dgp-20133\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκεσία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 261 na letra ι · nº geral 20133</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pedido de suplicante; súplica 2 prece: ἱκεσίας ποιεῖσθαι ésqn. dirigir preces aos deuses. 〈ἱκέσιος〉</p></section></article>\n<article id=\"entry-dgp-20134\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκέσιος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 262 na letra ι · nº geral 20134</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον 1 de suplicante 2 que protege suplicantes, epít. de Zeus e de Têmis 3 que faz suplicar: ἀναγκὰς ἱκεσίας λύσῃ eur. [pedindo que Teseu] me liberte dessas súplicas que não posso evitar 4 suplicante: ἱκέσιός σε λίσσομαι sóf. suplicante, eu te imploro. 〈ἱκέτης〉</p></section></article>\n<article id=\"entry-dgp-20135\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκεταδόκος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 263 na letra ι · nº geral 20135</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que acolhe suplicantes. 〈ἱκέτης, δέχομαι〉</p></section></article>\n<article id=\"entry-dgp-20136\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκετεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 264 na letra ι · nº geral 20136</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">súplica; prece. 〈ἱκετεύω〉</p></section></article>\n<article id=\"entry-dgp-20137\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκέτευμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 265 na letra ι · nº geral 20137</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">modo de súplica; forma de súplica. 〈ἱκετεύω〉</p></section></article>\n<article id=\"entry-dgp-20138\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκετευτέος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 266 na letra ι · nº geral 20138</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de ἱκετεύω.</p></section></article>\n<article id=\"entry-dgp-20139\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκετεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 267 na letra ι · nº geral 20139</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἱκέτευον, fut. ἱκετεύσω, aor. ἱκέτευσα, perf. desus.) 1 chegar como suplicante junto a alguém, ac. ou εἰς e ac.: σε φυγὼν ἱκέτευσα hom. fugitivo vim a ti como suplicante, ἐς Πηλῆ ἱκέτευσε hom. chegou suplicante junto a Peleu ♦ at. e méd. 2 suplicar a alguém, ac., gen. ou dat., algo, inf. ou or. conj. (ὡς): πρὸς γονάτων σε ἱκετεύομεν eur. junto de teus joelhos te suplicamos, ἱκετεύω σε πεισθῆναι μοι sóf. suplico que me obedeças, ἱκέτευσον πατρὸς τὴν σὴν ἀδελφὴν μὴ θανεῖν eur. suplica ao pai que tua irmã não morra 3 pedir suplicando; implorar: ὑπὲρ γὰρ οἴκου παντὸς ἱκετεύω τάδε eur. é por toda minha propriedade que te faço estas súplicas ♦ pas. 4 ser objeto de súplica. 〈ἱκέτης〉</p></section></article>\n<article id=\"entry-dgp-20140\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκετηρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 268 na letra ι · nº geral 20140</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἱκετήριος.</p></section></article>\n<article id=\"entry-dgp-20141\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκετήριος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 269 na letra ι · nº geral 20141</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de suplicante 2 suplicante ♦ ἡ ἱκετηρία [ἐλαία] 3 ramo de oliveira do suplicante: ἱκετηρίαν ἔθηκε παρ᾽ ὑμῖν dem. pôs diante de vós um ramo de suplicante, i.e., apresentou-se a vós como suplicante, ἱκετηρίαν δὲ γόνασιν ἐξάπτω σέθεν τὸ σῶμα τοὐμόν eur. como um ramo de suplicante, eu ligo meu corpo a teus joelhos 4 súplica. 〈ἱκέτης〉</p></section></article>\n<article id=\"entry-dgp-20142\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκέτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 270 na letra ι · nº geral 20142</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aquele que suplica ajuda ou proteção; suplicante, junto a alguém, gen., ou por alguém ou algo, gen. 〈ἱκνέομαι〉</p></section></article>\n<article id=\"entry-dgp-20143\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκετήσιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 271 na letra ι · nº geral 20143</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 protetor de suplicantes 2 suplicante. 〈ἱκέτης〉</p></section></article>\n<article id=\"entry-dgp-20144\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκέτις, ιδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 272 na letra ι · nº geral 20144</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">suplicante. 〈ἱκέτης〉</p></section></article>\n<article id=\"entry-dgp-20145\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἵκευ</h1><div class=\"entry-meta\"><span>DGP · ordem 273 na letra ι · nº geral 20145</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2a sing. aor.2 ép. de ἱκνέομαι.</p></section></article>\n<article id=\"entry-dgp-20146\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἵκηαι</h1><div class=\"entry-meta\"><span>DGP · ordem 274 na letra ι · nº geral 20146</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2a sing. subj. aor.2 ép. de ἱκνέομαι.</p></section></article>\n<article id=\"entry-dgp-20147\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰκμάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 275 na letra ι · nº geral 20147</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tornar úmido; umedecer ♦ pas. 2 estar ou ficar úmido. 〈ἰκμάς〉</p></section></article>\n<article id=\"entry-dgp-20148\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰκμάς, άδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 276 na letra ι · nº geral 20148</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 umidade (do ar) 2 toda substância úmida (oleosidade de couro) 3 elementos úmidos (do corpo humano); humores; secreções 4 suco: ἰκ. Βάκχου suco de Baco, i.e., vinho 5 resina: ἰκ. δρυός resina de carvalho.</p></section></article>\n<article id=\"entry-dgp-20149\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἴκμενος</h1><div class=\"entry-meta\"><span>DGP · ordem 277 na letra ι · nº geral 20149</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">só na loc. ἴκμενος οὖρος hom. vento favorável. 〈ἱκνέομαι〉</p></section></article>\n<article id=\"entry-dgp-20150\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκνέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 278 na letra ι · nº geral 20150</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἱκνούμην, fut. ἵξομαι, aor.2 ἱκόμην, perf. ἷγμαι) 1 (pessoa) vir; ir; chegar até alguém ou algum lugar, ac. ou εἰς, ἐπί, κατά, μετά e ac.: ἱκνεῖται Δίον πάμβοτον ἄλσος hom. [Io] chega ao fértil bosque de Zeus, ἵκοντο μετὰ Τρῶας καὶ Ἀχαιούς hom. [Príamo e Antenor] chegaram com os troianos e os aqueus, ἵκοντο κατ᾽ ἀσφοδελὸν λειμῶνα hom. [as almas dos pretendentes] desceram ao prado de asfódelos 2 (pessoa) chegar como suplicante até alguém ou à casa de alguém, ac. ou εἰς e ac.: Ζῆνα ἱξόμεσθα σὺν κλαδοῖς ésql. com ramos iremos suplicantes até Zeus 3 vir suplicar; pedir algo, ac. ou inf., a alguém, ac.: πάντες σ᾽ ἱκνοῦνται Δαναΐδαι θάψαι νεκρούς eur. todos os Daneidas te suplicam que sepultes os cadáveres 4 chegar; alcançar; atingir algo, ac. ou εἰς, μετά e ac.: πάρος ποσὶν οὖδας ἱκέσθαι hom. antes de [o dançarino] atingir o solo com os pés, οὐδέ μιν οἴω ἥβην ἵξεσθαι hom. nem creio que ele [Astíanax] alcance a juventude, ἐς γαῖάν τε καὶ οὐρανὸν ἵκετ᾽ ἀϋτμή hom. o grito atingia a terra e o céu, τίς ὁ πόθος αὐτοὺς ἵκετο; sóf. que pesar os atingia? 5 impes. ser conveniente; convir; caber a alguém, ac., algo, inf.: φαμὲν ἡμέας ἱκνέεσθαι ἡγεμονεύειν her. afirmamos que a nós cabe comandar, δικάζειν ἐς τὸν ἱκνέεται ἔχειν αὐτήν her. decidir a quem cabe possuí-la ♦ part. ἱκνούμενος, ép. ἱκνεύμενος, η, ον 6 conveniente: ἀντὶ τῶν νεῶν τὸ ἱκνούμενον ἀνάλωμα tuc. em vez das naus o imposto conveniente, μᾶλλον τοῦ ἱκνευμένον her. mais do que convém; excessivamente, ἐν χρόνῳ ἱκνευμένῳ her. em tempo conveniente,em tempo oportuno.</p></section></article>\n<article id=\"entry-dgp-20151\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκνεύμεναι</h1><div class=\"entry-meta\"><span>DGP · ordem 279 na letra ι · nº geral 20151</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. pres. ép., ἱκνεύμενος part. pres. ép., ἱκνεύμεσθα 1a pl. impf. ép., de ἱκνέομαι.</p></section></article>\n<article id=\"entry-dgp-20152\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκνευμένως</h1><div class=\"entry-meta\"><span>DGP · ordem 280 na letra ι · nº geral 20152</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ἱκνουμένως.</p></section></article>\n<article id=\"entry-dgp-20153\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκνούμενος,</h1><div class=\"entry-meta\"><span>DGP · ordem 281 na letra ι · nº geral 20153</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. ἱκνεύμενος, η, ον cf. ἱκνέομαι.</p></section></article>\n<article id=\"entry-dgp-20154\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκνουμένως</h1><div class=\"entry-meta\"><span>DGP · ordem 282 na letra ι · nº geral 20154</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de modo suficiente; convenientemente.</p></section></article>\n<article id=\"entry-dgp-20155\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκοίατο</h1><div class=\"entry-meta\"><span>DGP · ordem 283 na letra ι · nº geral 20155</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3a pl. opt. aor.2 ép. de ἱκνέομαι.</p></section></article>\n<article id=\"entry-dgp-20156\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκόμην</h1><div class=\"entry-meta\"><span>DGP · ordem 284 na letra ι · nº geral 20156</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἱκνέομαι.</p></section></article>\n<article id=\"entry-dgp-20157\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰκόνιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 285 na letra ι · nº geral 20157</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Icônio, cidade da Licaônia ou da Frígia.</p></section></article>\n<article id=\"entry-dgp-20158\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἴκριον</h1><div class=\"entry-meta\"><span>DGP · ordem 286 na letra ι · nº geral 20158</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ἰκρίον, ου (τό) 1 castelo de popa ou de proa 2 estrado; plataforma 3 banco (de teatro).</p></section></article>\n<article id=\"entry-dgp-20159\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰκριόφι(ν)</h1><div class=\"entry-meta\"><span>DGP · ordem 287 na letra ι · nº geral 20159</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. e dat. ép de ἴκριον.</p></section></article>\n<article id=\"entry-dgp-20160\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκταῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 288 na letra ι · nº geral 20160</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">suplicante. 〈ἱκνέομαι〉</p></section></article>\n<article id=\"entry-dgp-20161\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἴκταρ</h1><div class=\"entry-meta\"><span>DGP · ordem 289 na letra ι · nº geral 20161</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 de forma ininterrupta; sem cessar ♦ prep. 2 perto de; próximo de, gen.</p></section></article>\n<article id=\"entry-dgp-20162\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰκτεριάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 290 na letra ι · nº geral 20162</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ter icterícia. 〈ἴκτερος〉</p></section></article>\n<article id=\"entry-dgp-20163\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἴκτερος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 291 na letra ι · nº geral 20163</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Medic. icterícia.</p></section></article>\n<article id=\"entry-dgp-20164\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκτήρ, ῆρος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 292 na letra ι · nº geral 20164</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 suplicante 2 protetor dos suplicantes ♦ adj. 3 de suplicante (ramo). 〈ἱκνέομαι〉</p></section></article>\n<article id=\"entry-dgp-20165\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱκτήριος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 293 na letra ι · nº geral 20165</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de suplicante ♦ οἱ ἱκτήριοι 2 os suplicantes ♦ ἡ ἱκτηρία 3 ramo de suplicante. 〈ἱκτήρ〉</p></section></article>\n<article id=\"entry-dgp-20166\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰκτῖνος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 294 na letra ι · nº geral 20166</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 milhafre, ave de rapina 2 espécie de lobo.</p></section></article>\n<article id=\"entry-dgp-20167\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἵκτιος</h1><div class=\"entry-meta\"><span>DGP · ordem 295 na letra ι · nº geral 20167</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἱκταῖος.</p></section></article>\n<article id=\"entry-dgp-20168\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἴκτις, ιδος</h1><div class=\"entry-meta\"><span>DGP · ordem 296 na letra ι · nº geral 20168</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ἰκτίς, ίδος (ἡ) fuinha, animal.</p></section></article>\n<article id=\"entry-dgp-20169\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἵκτωρ, ορος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 297 na letra ι · nº geral 20169</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἱκέτης.</p></section></article>\n<article id=\"entry-dgp-20170\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἵκω</h1><div class=\"entry-meta\"><span>DGP · ordem 298 na letra ι · nº geral 20170</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἷκον, fut. ἵξομαι, aor.2 ἷξον e aor.1 ἷξα) poét. 1 vir a um lugar, ac. ou εἰς, ἐπί ou κατά e ac.: ἵκ. δόμον hom., ἐς δόμον hom. vir à casa, ἵκ. ἐς Πριάμοιο hom. vir ao palácio de Príamo; com part. ἵκ. θέων hom., νέων hom. vir correndo, nadando 2 (coisa) vir até; atingir alguém ou algo, ac. ou ἐς e ac.: ἀϋτὴ δ᾽ οὐρανὸν ἵκεν hom. o alarido chegava ao céu 3 (coisa) invadir alguém, ac.: ἵκει με χρειώ hom. a necessidade me invade.</p></section></article>\n<article id=\"entry-dgp-20171\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἵκωμι</h1><div class=\"entry-meta\"><span>DGP · ordem 299 na letra ι · nº geral 20171</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pres. subj. ép. de ἵκω.</p></section></article>\n<article id=\"entry-dgp-20172\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἴλα</h1><div class=\"entry-meta\"><span>DGP · ordem 300 na letra ι · nº geral 20172</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = ἴλη.</p></section></article>\n<article id=\"entry-dgp-20173\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰλαδόν</h1><div class=\"entry-meta\"><span>DGP · ordem 301 na letra ι · nº geral 20173</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 em bando; em massa 2 em grande quantidade; abundantemente. 〈ἴλη〉</p></section></article>\n<article id=\"entry-dgp-20174\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱλάειρα, ας</h1><div class=\"entry-meta\"><span>DGP · ordem 302 na letra ι · nº geral 20174</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) beneficente; benéfico. 〈ἵλαος〉</p></section></article>\n<article id=\"entry-dgp-20175\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱλάομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 303 na letra ι · nº geral 20175</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) ép. = ἱλάσκομαι.</p></section></article>\n<article id=\"entry-dgp-20176\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἵλαος, ος, ον,</h1><div class=\"entry-meta\"><span>DGP · ordem 304 na letra ι · nº geral 20176</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ἵλεως, ως, ων 1 favorável; propício a alguém, dat. 2 benévolo; amável (pessoa) 3 de bom humor; alegre. 〈ἱλάσκομαι〉</p></section></article>\n<article id=\"entry-dgp-20177\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱλαρός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 305 na letra ι · nº geral 20177</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 alegre; divertido; aprazível ♦ τὸ ἱλαρόν 2 alegria; prazer.</p></section></article>\n<article id=\"entry-dgp-20178\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱλαρότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 306 na letra ι · nº geral 20178</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">alegria. 〈ἱλαρός〉</p></section></article>\n<article id=\"entry-dgp-20179\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱλαρῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 307 na letra ι · nº geral 20179</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. alegremente.</p></section></article>\n<article id=\"entry-dgp-20180\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱλάσιμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 308 na letra ι · nº geral 20180</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que pode ser aplacado; acessivel à piedade 2 propiciatório. 〈ἱλάσκομαι〉</p></section></article>\n<article id=\"entry-dgp-20181\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱλάσκομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 309 na letra ι · nº geral 20181</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἱλάσομαι, aor. ἱλασάμην, perf. desus.) 1 tornar propício; tornar favorável alguém, ac.: θυσίησι αὐτὸν ἱλάσκονται her. com sacrifícios o tornam propício, Θεμιστοκλέα χρήμασι ἱλασάμενοι her. tendo, com dinheiro, tornado Temístocles favorável 2 apaziguar, ac.: θεὸν ἱλάσκεσθαι hom. apaziguar o deus, ἱλασκεσθαι τὴν ὀργήν τινος plut. apaziguar a cólera de alguém 3 bíbl. expiar (pecado) 4 bíbl. perdoar ♦ pas. 5 ser misericorioso; ter piedade de, dat.: ἱλάσθηθί μοι n.t. tem piedade de mim. 〈ἵλαος〉</p></section></article>\n<article id=\"entry-dgp-20182\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱλασμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 310 na letra ι · nº geral 20182</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de tornar propício (por meio de cerimônia expiatória) 2 modo de apaziguar 3 expiação. 〈ἱλάσκομαι〉</p></section></article>\n<article id=\"entry-dgp-20183\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱλασσάμενος</h1><div class=\"entry-meta\"><span>DGP · ordem 311 na letra ι · nº geral 20183</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor. ép., ἱλάσσεαι 2a sing. subj. aor. ép., ἱλάσσομαι fut. ép., de ἱλάσκομαι.</p></section></article>\n<article id=\"entry-dgp-20184\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱλαστήριος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 312 na letra ι · nº geral 20184</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 propiciatório ♦ τὸ ἱλαστήριον 2 oferenda propiciatória ou expiatória 3 propiciatório, entre os judeus, placa sobre a arca sagrada. 〈ἱλάσκομαι〉</p></section></article>\n<article id=\"entry-dgp-20185\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱλέομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 313 na letra ι · nº geral 20185</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) jôn. = ἱλάομαι.</p></section></article>\n<article id=\"entry-dgp-20186\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱλεόομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 314 na letra ι · nº geral 20186</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἱλάομαι.</p></section></article>\n<article id=\"entry-dgp-20187\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἵλεως, ως, ων</h1><div class=\"entry-meta\"><span>DGP · ordem 315 na letra ι · nº geral 20187</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = ἵλαος, ος, ον.</p></section></article>\n<article id=\"entry-dgp-20188\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱλέως</h1><div class=\"entry-meta\"><span>DGP · ordem 316 na letra ι · nº geral 20188</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. favoravelmente.</p></section></article>\n<article id=\"entry-dgp-20189\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἴλη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 317 na letra ι · nº geral 20189</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tropa (de homens ou de animais) 2 Mil. companhia; pelotão; esquadrão (de cavaleiros): κατ᾽ ἴλας por companhias 3 grupo de jovens, em Esparta.</p></section></article>\n<article id=\"entry-dgp-20190\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἵληθι</h1><div class=\"entry-meta\"><span>DGP · ordem 318 na letra ι · nº geral 20190</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2a sing. pres. imper. de ἵλημι.</p></section></article>\n";
